import { decompress } from './decompress.ts';
import {
  openWebSocket,
  type WebSocketAdapter,
  type WebSocketArgs,
} from './ws.ts';

export class WebsocketDecompressAdapter implements WebSocketAdapter {
  get protocol(): string {
    return this.#ws.protocol;
  }
  get readyState(): number {
    return this.#ws.readyState;
  }
  set onclose(handler: (ev: CloseEvent) => void) {
    this.#ws.onclose = handler;
  }
  set onopen(handler: () => void) {
    this.#ws.onopen = handler;
  }
  set onmessage(handler: (msg: { data: Uint8Array }) => void) {
    let tail: Promise<void> = Promise.resolve();
    this.#ws.onmessage = async (msg: MessageEvent<ArrayBuffer>) => {
      const pending = this.#decompress(new Uint8Array(msg.data));
      // Mark the rejection handled now: the chain may not reach this frame for
      // several ticks, and without this an inflate failure surfaces as an
      // unhandledrejection in the meantime. Awaiting pending still throws it.
      pending.catch(() => {});

      // Reserve this frame's position before yielding, while decompression
      // proceeds concurrently with earlier frames.
      const previous = tail;
      let release!: () => void;
      tail = new Promise<void>(resolve => {
        release = resolve;
      });

      try {
        await previous;

        let data: Uint8Array;
        try {
          data = await pending;
        } catch (e) {
          // A decompression failure (e.g. WebKit's DecompressionStream rejecting
          // with "Incomplete compressed input.") would otherwise become an
          // unhandled rejection: the frame is silently dropped and the
          // connection stalls without ever reaching onDisconnect. Close the
          // socket instead so the caller's disconnect/reconnect handling
          // takes over.
          console.error(
            '[SpacetimeDB] WebSocket decompress failed, closing socket:',
            e
          );
          this.#ws.close();
          return;
        }
        handler({ data });
      } finally {
        // Handler exceptions must not prevent delivery of subsequent frames.
        release();
      }
    };
  }
  set onerror(handler: (msg: ErrorEvent) => void) {
    this.#ws.onerror = handler as (msg: Event) => void;
  }

  #ws: WebSocket;

  async #decompress(buffer: Uint8Array<ArrayBuffer>): Promise<Uint8Array> {
    const tag = buffer[0];
    const data = buffer.subarray(1);
    switch (tag) {
      case 0:
        return data;
      case 1:
        // Some runtimes support brotli, but it's not yet defined in `lib.dom.d.ts`.
        // We assert runtime support in `DbConnectionBuilder.withCompression`, so
        // this cast is safe.
        return await decompress(data, 'brotli' as CompressionFormat);
      case 2:
        return await decompress(data, 'gzip');
      default:
        throw new Error(
          'Unexpected Compression Algorithm. Please use `gzip` or `none`'
        );
    }
  }

  send(msg: Uint8Array<ArrayBuffer>): void {
    this.#ws.send(msg);
  }

  close(): void {
    this.#ws.close();
  }

  constructor(ws: WebSocket) {
    this.#ws = ws;
  }

  static async openWebSocket(
    args: WebSocketArgs
  ): Promise<WebsocketDecompressAdapter> {
    return new WebsocketDecompressAdapter(await openWebSocket(args));
  }
}
