import type { ParamsObj } from '../lib/reducers.ts';
import type {
  Infer,
  InferTypeOfParams,
  TypeBuilder,
} from '../lib/type_builders.ts';
import type { CamelCase, NestAccessors } from '../lib/type_util.ts';
import { coerceParams, toCamelCase, type CoerceParams } from '../lib/util.ts';
import type { UntypedRemoteModule } from './spacetime_module.ts';

// Utility: detect 'any'
type IfAny<T, Y, N> = 0 extends 1 & T ? Y : N;

// Loose shape that allows all three families even when key names are unknown.
type ProceduresViewLoose = { readonly [k: string]: any };

export type ProceduresView<RemoteModule> = IfAny<
  RemoteModule,
  ProceduresViewLoose,
  RemoteModule extends UntypedRemoteModule
    ? NestAccessors<{
        [K in RemoteModule['procedures'][number] as K['accessorName']]: (
          params: InferTypeOfParams<K['params']>
        ) => Promise<Infer<K['returnType']>>;
      }>
    : never
>;

export type UntypedProcedureDef = {
  name: string;
  accessorName: string;
  params: CoerceParams<ParamsObj>;
  returnType: TypeBuilder<any, any>;
};

export type UntypedProceduresDef = {
  procedures: readonly UntypedProcedureDef[];
};

export function procedures<const H extends readonly UntypedProcedureDef[]>(
  ...handles: H
): { procedures: H };

export function procedures<const H extends readonly UntypedProcedureDef[]>(
  handles: H
): { procedures: H };

export function procedures<const H extends readonly UntypedProcedureDef[]>(
  ...args: [H] | H
): { procedures: H } {
  const procedures = (
    args.length === 1 && Array.isArray(args[0]) ? args[0] : args
  ) as H;
  return { procedures };
}

type ProcedureDef<
  Name extends string,
  Params extends ParamsObj,
  ReturnType extends TypeBuilder<any, any>,
  AccessorName extends string = CamelCase<Name>,
> = {
  name: Name;
  accessorName: AccessorName;
  params: CoerceParams<Params>;
  returnType: ReturnType;
};

export function procedureSchema<
  ProcedureName extends string,
  Params extends ParamsObj,
  ReturnType extends TypeBuilder<any, any>,
  AccessorName extends string = CamelCase<ProcedureName>,
>(
  name: ProcedureName,
  params: Params,
  returnType: ReturnType,
  accessorName?: AccessorName
): ProcedureDef<ProcedureName, Params, ReturnType, AccessorName> {
  return {
    name,
    accessorName: accessorName ?? (toCamelCase(name) as AccessorName),
    params: coerceParams(params),
    returnType,
  };
}
