import { stdbLogger } from './logger.ts';

async function resolveWS(): Promise<typeof WebSocket> {
  // Browser or Node >= 22 (or any env that exposes global WebSocket)
  if (typeof WebSocket !== 'undefined') {
    return WebSocket;
  }

  // Node without a global WebSocket: lazily load undici's polyfill.
  // Use an unstatable dynamic import so bundlers don't prebundle it.
  const dynamicImport = new Function('m', 'return import(m)') as (
    m: string
  ) => Promise<any>;

  try {
    const { WebSocket: UndiciWS } = await dynamicImport('undici');
    return UndiciWS as unknown as typeof WebSocket;
  } catch (err) {
    stdbLogger(
      'warn',
      '[spacetimedb-sdk] No global WebSocket found. ' +
        'On Node 18–21, please install `undici` (npm install undici) ' +
        'to enable WebSocket support.'
    );
    throw err;
  }
}

export interface WebSocketAdapter {
  readonly protocol: string;
  /**
   * The underlying socket's `readyState`, using the standard `WebSocket`
   * constants: `CONNECTING` (0), `OPEN` (1), `CLOSING` (2), `CLOSED` (3). Used
   * to detect sockets that died silently, for example after the tab was frozen
   * or the machine slept, without a clean `onclose` having fired.
   *
   * Optional so existing custom adapters stay valid without changes. When an
   * adapter does not expose it, the resume handler cannot detect a
   * silently-closed socket for that adapter and leaves it to the normal
   * `onclose` path.
   */
  readonly readyState?: number;
  send(msg: Uint8Array<ArrayBuffer>): void;
  close(): void;

  set onclose(handler: (ev: CloseEvent) => void);
  set onopen(handler: () => void);
  set onmessage(handler: (msg: { data: Uint8Array }) => void);
  set onerror(handler: (msg: ErrorEvent) => void);
}

export class WebSocketTokenError extends Error {
  constructor(
    readonly status: number,
    statusText: string
  ) {
    super(`Failed to verify token: ${status} ${statusText}`);
    this.name = 'WebSocketTokenError';
  }
}

export interface WebSocketArgs {
  url: URL;
  wsProtocol: string[];
  nameOrAddress: string;
  authToken?: string;
  compression: 'gzip' | 'brotli' | 'none';
  lightMode: boolean;
  confirmedReads?: boolean;
  /** Hex-encoded id for this socket. */
  connectionId?: string;
  /** Stable session id, sent only when automatic reconnection is enabled. */
  sessionId?: string;
}
export type WebSocketFactory = (
  args: WebSocketArgs
) => Promise<WebSocketAdapter>;

/**
 * Open a WebSocket to the database specified by the given `WebSocketArgs`.
 * @returns a WebSocket with `binaryType` set to `arraybuffer`.
 */
export async function openWebSocket({
  url,
  nameOrAddress,
  wsProtocol,
  authToken,
  compression,
  lightMode,
  confirmedReads,
  connectionId,
  sessionId,
}: WebSocketArgs): Promise<WebSocket> {
  const headers = new Headers();

  const WS = await resolveWS();

  // We swap our original token to a shorter-lived token
  // to avoid sending the original via query params.
  let temporaryAuthToken: string | undefined;
  if (authToken) {
    headers.set('Authorization', `Bearer ${authToken}`);
    const tokenUrl = new URL('v1/identity/websocket-token', url);
    tokenUrl.protocol = url.protocol === 'wss:' ? 'https:' : 'http:';

    const response = await fetch(tokenUrl, { method: 'POST', headers });
    if (response.ok) {
      const { token } = await response.json();
      temporaryAuthToken = token;
    } else {
      throw new WebSocketTokenError(response.status, response.statusText);
    }
  }

  const databaseUrl = new URL(`v1/database/${nameOrAddress}/subscribe`, url);
  if (temporaryAuthToken) {
    databaseUrl.searchParams.set('token', temporaryAuthToken);
  }
  databaseUrl.searchParams.set(
    'compression',
    { gzip: 'Gzip', brotli: 'Brotli', none: 'None' }[compression] ?? 'None'
  );
  if (lightMode) {
    databaseUrl.searchParams.set('light', 'true');
  }
  if (confirmedReads !== undefined) {
    databaseUrl.searchParams.set('confirmed', confirmedReads.toString());
  }
  // Note that `url`'s own query parameters are not carried over by the `URL`
  // constructor above, so these must be set here.
  if (connectionId) {
    databaseUrl.searchParams.set('connection_id', connectionId);
  }
  if (sessionId) {
    databaseUrl.searchParams.set('session_id', sessionId);
  }

  const ws = new WS(databaseUrl.toString(), wsProtocol);
  ws.binaryType = 'arraybuffer';
  return ws;
}
